def remove_flags(text):
    # Regex to remove flag emojis and random other symbols that we want to just clear
    # We will just replace them with empty string if not in svg_map
    return text

def replace_emojis(folder_path):
    for root, dirs, files in os.walk(folder_path):
        if 'node_modules' in dirs:
            dirs.remove('node_modules')
        for file in files:
            if file.endswith('.html'):
                file_path = os.path.join(root, file)
                try:
                    with open(file_path, 'r', encoding='utf-8') as f:
                        content = f.read()
                        
                    new_content = content
                    for emoji, replacement in svg_map.items():
                        new_content = new_content.replace(emoji, replacement)
                    
                    # Also strip flag characters and a few missed ones if needed
                    # Actually let's do a simple regex for remaining non-svg emojis that might be decorative
                    emoji_pattern = re.compile(
                        r'['
                        r'\U0001f600-\U0001f64f'  # emoticons
                        r'\U0001f300-\U0001f5ff'  # symbols & pictographs
                        r'\U0001f680-\U0001f6ff'  # transport & map symbols
                        r'\U0001f1e0-\U0001f1ff'  # flags (iOS)
                        r'\u2700-\u27bf'          # dingbats
                        r']+',
                        re.UNICODE
                    )
                    
                    def repl(match):
                        return ''  # remove them
                        
                    new_content = emoji_pattern.sub(repl, new_content)

                    if new_content != content:
                        with open(file_path, 'w', encoding='utf-8') as f:
                            f.write(new_content)
                        print(f"Updated {file_path}")
                except Exception as e:
                    print(f"Error processing {file_path}: {e}")

if __name__ == "__main__":
    replace_emojis('.')
